class Bus:
    def __init__(self):
        self.handlers = []
    def subscribe(self, fn):
        self.handlers.append(fn)
    def publish(self, msg):
        for fn in self.handlers:
            fn(msg)
bus = Bus()
for n in range(3):  # the dialog is opened and closed three times
    bus.subscribe(lambda msg: print("dialog got", msg))
bus.publish("saved")

interface Text { String render(); }
class Plain implements Text {
    public String render() { return "hi"; }
}
class Bold implements Text {
    private final Text inner;
    Bold(Text inner) { this.inner = inner; }
    public String render() { return "<b>" + inner.render() + "</b>"; }
}
// Italic is written the same way, with <i> and </i>
Text t = new Italic(new Bold(new Plain()));
System.out.println(t.render());
